Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing

$AppName = "POS Factory"
$AppVersion = "2.3.0"
$AppExeName = "pos_offline_desktop.exe"
$InstallDir = Join-Path $env:ProgramFiles $AppName
$base64Zip = "'@; $footer = @'"

function Test-Admin { $p = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent()); return $p.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator) }
function Show-Msg { param([string]$Msg, [string]$Title = "POS Factory", [System.Windows.Forms.MessageBoxButtons]$Btns = [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]$Icon = [System.Windows.Forms.MessageBoxIcon]::Information); return [System.Windows.Forms.MessageBox]::Show($Msg, $Title, $Btns, $Icon) }

function Show-Welcome {
    $f = New-Object System.Windows.Forms.Form
    $f.Text = "$AppName v$AppVersion - Setup"
    $f.Size = New-Object System.Drawing.Size(560, 380)
    $f.StartPosition = "CenterScreen"
    $f.FormBorderStyle = "FixedDialog"
    $f.MaximizeBox = $false
    $f.BackColor = [System.Drawing.Color]::White
    $f.Font = New-Object System.Drawing.Font("Segoe UI", 9)

    $hdr = New-Object System.Windows.Forms.Panel
    $hdr.Location = New-Object System.Drawing.Point(0, 0)
    $hdr.Size = New-Object System.Drawing.Size(560, 80)
    $hdr.BackColor = [System.Drawing.Color]::FromArgb(0, 120, 215)
    $f.Controls.Add($hdr)

    $lblTitle = New-Object System.Windows.Forms.Label
    $lblTitle.Text = "$AppName v$AppVersion"
    $lblTitle.Location = New-Object System.Drawing.Point(25, 15)
    $lblTitle.Size = New-Object System.Drawing.Size(510, 30)
    $lblTitle.Font = New-Object System.Drawing.Font("Segoe UI", 16, [System.Drawing.FontStyle]::Bold)
    $lblTitle.ForeColor = [System.Drawing.Color]::White
    $lblTitle.BackColor = [System.Drawing.Color]::Transparent
    $hdr.Controls.Add($lblTitle)

    $lblSub = New-Object System.Windows.Forms.Label
    $lblSub.Text = "DEVELOPED BY MO2 | 01025545211"
    $lblSub.Location = New-Object System.Drawing.Point(25, 50)
    $lblSub.Size = New-Object System.Drawing.Size(510, 25)
    $lblSub.Font = New-Object System.Drawing.Font("Segoe UI", 9)
    $lblSub.ForeColor = [System.Drawing.Color]::FromArgb(200, 220, 240)
    $lblSub.BackColor = [System.Drawing.Color]::Transparent
    $hdr.Controls.Add($lblSub)

    $lblBody = New-Object System.Windows.Forms.Label
    $lblBody.Text = "New Features:`n  + QR Code Support`n  + Enhanced Customer Management`n  + Delete Customer from Edit Page`n`nFixes:`n  + Fixed security warnings issue`n  + Improved stability"
    $lblBody.Location = New-Object System.Drawing.Point(25, 95)
    $lblBody.Size = New-Object System.Drawing.Size(510, 180)
    $lblBody.Font = New-Object System.Drawing.Font("Segoe UI", 10)
    $f.Controls.Add($lblBody)

    $btnInstall = New-Object System.Windows.Forms.Button
    $btnInstall.Text = "Install"
    $btnInstall.Location = New-Object System.Drawing.Point(380, 290)
    $btnInstall.Size = New-Object System.Drawing.Size(150, 40)
    $btnInstall.Font = New-Object System.Drawing.Font("Segoe UI", 10, [System.Drawing.FontStyle]::Bold)
    $btnInstall.BackColor = [System.Drawing.Color]::FromArgb(0, 120, 215)
    $btnInstall.ForeColor = [System.Drawing.Color]::White
    $btnInstall.FlatStyle = "Flat"
    $btnInstall.FlatAppearance.BorderSize = 0
    $btnInstall.Cursor = [System.Windows.Forms.Cursors]::Hand
    $btnInstall.Add_Click({ $f.Tag = "go"; $f.Close() })
    $f.Controls.Add($btnInstall)

    $btnCancel = New-Object System.Windows.Forms.Button
    $btnCancel.Text = "Cancel"
    $btnCancel.Location = New-Object System.Drawing.Point(220, 290)
    $btnCancel.Size = New-Object System.Drawing.Size(150, 40)
    $btnCancel.Font = New-Object System.Drawing.Font("Segoe UI", 9)
    $btnCancel.BackColor = [System.Drawing.Color]::FromArgb(240, 240, 240)
    $btnCancel.FlatStyle = "Flat"
    $btnCancel.Cursor = [System.Windows.Forms.Cursors]::Hand
    $btnCancel.Add_Click({ $f.Tag = "cancel"; $f.Close() })
    $f.Controls.Add($btnCancel)

    $f.ShowDialog() | Out-Null
    return $f.Tag
}

function Show-Progress {
    param([string]$ZipPath, [string]$DestPath)

    $f = New-Object System.Windows.Forms.Form
    $f.Text = "Installing $AppName v$AppVersion..."
    $f.Size = New-Object System.Drawing.Size(460, 250)
    $f.StartPosition = "CenterScreen"
    $f.FormBorderStyle = "FixedDialog"
    $f.MaximizeBox = $false
    $f.BackColor = [System.Drawing.Color]::White
    $f.Font = New-Object System.Drawing.Font("Segoe UI", 9)

    $lbl = New-Object System.Windows.Forms.Label
    $lbl.Text = "Installing..."
    $lbl.Location = New-Object System.Drawing.Point(25, 20)
    $lbl.Size = New-Object System.Drawing.Size(410, 30)
    $lbl.Font = New-Object System.Drawing.Font("Segoe UI", 13, [System.Drawing.FontStyle]::Bold)
    $lbl.ForeColor = [System.Drawing.Color]::FromArgb(0, 120, 215)
    $f.Controls.Add($lbl)

    $lblStatus = New-Object System.Windows.Forms.Label
    $lblStatus.Text = "Preparing..."
    $lblStatus.Location = New-Object System.Drawing.Point(25, 65)
    $lblStatus.Size = New-Object System.Drawing.Size(410, 25)
    $f.Controls.Add($lblStatus)

    $pb = New-Object System.Windows.Forms.ProgressBar
    $pb.Location = New-Object System.Drawing.Point(25, 105)
    $pb.Size = New-Object System.Drawing.Size(410, 25)
    $pb.Style = "Marquee"
    $pb.MarqueeAnimationSpeed = 30
    $f.Controls.Add($pb)

    $lblDetail = New-Object System.Windows.Forms.Label
    $lblDetail.Text = ""
    $lblDetail.Location = New-Object System.Drawing.Point(25, 145)
    $lblDetail.Size = New-Object System.Drawing.Size(410, 30)
    $lblDetail.ForeColor = [System.Drawing.Color]::Gray
    $f.Controls.Add($lblDetail)

    $btnFinish = New-Object System.Windows.Forms.Button
    $btnFinish.Text = "Finish"
    $btnFinish.Location = New-Object System.Drawing.Point(310, 180)
    $btnFinish.Size = New-Object System.Drawing.Size(120, 35)
    $btnFinish.Font = New-Object System.Drawing.Font("Segoe UI", 10, [System.Drawing.FontStyle]::Bold)
    $btnFinish.BackColor = [System.Drawing.Color]::FromArgb(0, 120, 215)
    $btnFinish.ForeColor = [System.Drawing.Color]::White
    $btnFinish.FlatStyle = "Flat"
    $btnFinish.FlatAppearance.BorderSize = 0
    $btnFinish.Enabled = $false
    $btnFinish.Add_Click({ $f.Tag = "done"; $f.Close() })
    $f.Controls.Add($btnFinish)

    $f.Add_Shown({
        Get-Process -Name "pos_offline_desktop" -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
        Start-Sleep -Seconds 2

        $lblStatus.Text = "Creating directory..."
        $f.Refresh()
        if (-not (Test-Path $DestPath)) { New-Item -ItemType Directory -Path $DestPath -Force | Out-Null }
        Start-Sleep -Milliseconds 500

        $lblStatus.Text = "Extracting files..."
        $lblDetail.Text = "This may take a moment..."
        $f.Refresh()
        try {
            Expand-Archive -Path $ZipPath -DestinationPath $DestPath -Force
            Start-Sleep -Seconds 1
        } catch {
            Show-Msg -Msg "Extraction failed: $_" -Icon "Error"
            $f.Tag = "err"
            $f.Close()
            return
        }

        $lblStatus.Text = "Creating shortcuts..."
        $f.Refresh()
        try {
            $ws = New-Object -ComObject WScript.Shell
            $sc1 = $ws.CreateShortcut("$env:Public\Desktop\$AppName.lnk")
            $sc1.TargetPath = Join-Path $DestPath $AppExeName
            $sc1.WorkingDirectory = $DestPath
            $sc1.Save()
            $sc2 = $ws.CreateShortcut("$env:ProgramData\Microsoft\Windows\Start Menu\Programs\$AppName.lnk")
            $sc2.TargetPath = Join-Path $DestPath $AppExeName
            $sc2.WorkingDirectory = $DestPath
            $sc2.Save()
        } catch { }

        $lblStatus.Text = "Installation completed!"
        $lblStatus.ForeColor = [System.Drawing.Color]::FromArgb(0, 128, 0)
        $pb.Style = "Continuous"
        $pb.Value = 100
        $btnFinish.Enabled = $true
        $f.Refresh()
    })

    $f.ShowDialog() | Out-Null
    return $f.Tag
}

if (-not (Test-Admin)) { Show-Msg -Msg "Please run as administrator." -Icon "Warning"; exit }

$result = Show-Welcome
if ($result -ne "go") { exit }

$tempZip = Join-Path $env:TEMP "pos_factory_package.zip"
try { [IO.File]::WriteAllBytes($tempZip, [Convert]::FromBase64String($base64Zip)) } catch { Show-Msg -Msg "Failed to extract installer package." -Icon "Error"; exit }

$installResult = Show-Progress -ZipPath $tempZip -DestPath $InstallDir

# FEAT-013: the customer's license file is deliberately NOT cleared here.
# An application update must never cost a paying customer their license.
# The former step targeted %APPDATA%\com.example\pos_offline_desktop while the
# app writes to %APPDATA%\pos_offline_desktop — wrong path, so it was a no-op,
# but removing the code prevents a future "path fix" from destroying licenses.
# Guard: test/unit/services/installer_license_persistence_test.dart

if ($installResult -eq "done") {
    $lr = Show-Msg -Msg "$AppName v$AppVersion installed successfully!`n`nLaunch now?" -Buttons "YesNo" -Icon "Information"
    if ($lr -eq "Yes") { $exe = Join-Path $InstallDir $AppExeName; if (Test-Path $exe) { Start-Process -FilePath $exe } }
}

Remove-Item $tempZip -Force -ErrorAction SilentlyContinue

